-- 阿风脚本 | 加密包 (请勿直接修改，源码在仓库外维护)
local D=[[]]
local B="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local M={} for i=1,64 do M[B:sub(i,i)]=i-1 end
local acc,bit,out=0,0,{}
for c in D:gmatch(".") do local v=M[c] if v then acc=acc*64+v bit=bit+6 if bit>=8 then bit=bit-8 local p=2^bit out[#out+1]=string.char(acc//p%256) acc=acc%p end end end
local f=loadstring or load
if not f then warn("[阿风脚本] 不支持 loadstring") return end
local ok,e=pcall(function() f(table.concat(out))() end)
if not ok then warn("[阿风脚本] "..tostring(e)) end
